def tr(M,k,flip):
 A=[row[:] for row in M]
 if flip: A=[row[::-1] for row in A]
 for _ in range(k): A=[list(x) for x in zip(*A[::-1])]
 return A
ops={'and':lambda x,y:x&y,'or':lambda x,y:x|y,'xor':lambda x,y:x^y,'a-b':lambda x,y:x& (1-y),'b-a':lambda x,y:y&(1-x),'eq':lambda x,y:int(x==y),'nor':lambda x,y:1-(x|y)}
for f in (0,1):
 for k in range(4):
  scores={op:[] for op in ops}
  for a,b,o in D:
   t=tr(b,k,f)
   for op,fn in ops.items(): scores[op].append(sum(fn(a[i][j],t[i][j])==o[i][j] for i in range(4) for j in range(4)))
  best=max((sum(sc),op,sc) for op,sc in scores.items())
  if best[0]>=25: print('flip',f,'rot',k,best)

